const dialoguesData = await read("public/data/dialogues.json");
const newDialogues = dialogueRows.map(([title, context, level, theme, lines], index) =>
  D(`ADV-D${String(index + 1).padStart(2, "0")}`, title, context, level, theme, lines.map(([speaker, english, portuguese]) => L(speaker, english, portuguese))),
);
dialoguesData.dialogues = [...dialoguesData.dialogues.filter((item) => !item.id.startsWith("ADV-D")), ...newDialogues];
dialoguesData.meta = { ...dialoguesData.meta, count: dialoguesData.dialogues.length, schemaVersion: 3 };
await out("public/data/dialogues.json", dialoguesData);

