const advancedGrammar = [
  ["G25", "C1", "Inversão para ênfase", "Depois de expressões negativas, o auxiliar vem antes do sujeito.", "Rarely/Never/Only then + auxiliary + subject + verb", "Ouça a expressão inicial e espere a ordem de pergunta, mesmo em uma afirmação.", "Não inverta sem o gatilho: diga I rarely see, mas Rarely do I see.", [["Rarely do we get a second chance.", "Raramente temos uma segunda chance."], ["Only then did I understand the risk.", "Só então entendi o risco."]]],
  ["G26", "C1", "Cleft sentences", "Estruturas com it e what deslocam o foco para uma informação.", "It was X that... · What I need is...", "A palavra depois de was/is recebe o maior destaque sonoro.", "Mantenha a concordância depois de what como uma unidade.", [["What I need is a clear answer.", "O que preciso é de uma resposta clara."], ["It was Maya who spotted the error.", "Foi Maya quem percebeu o erro."]]],
  ["G27", "C1", "Participle clauses", "Orações reduzidas com -ing ou particípio conectam ideias de forma compacta.", "Having + participle... · Given + noun...", "A pausa inicial separa a circunstância da oração principal.", "O sujeito implícito deve ser o mesmo da oração principal.", [["Having reviewed the logs, we rolled back.", "Após revisar os logs, fizemos a reversão."], ["Given the delay, we changed course.", "Dado o atraso, mudamos de rumo."]]],
  ["G28", "C1", "Hedging e cautela", "Might, appears, tends to e arguably reduzem a força de uma afirmação.", "subject + may/might/appears to/tends to", "Essas palavras curtas mudam a certeza; não as descarte como ruído.", "Não traduza hedge como insegurança automática; pode ser precisão acadêmica.", [["The change appears to have helped.", "A mudança parece ter ajudado."], ["This may partly explain the gap.", "Isso pode explicar parcialmente a diferença."]]],
  ["G29", "C1", "Future in the past", "Would e was going to descrevem um futuro visto de um ponto passado.", "would + verb · was/were going to + verb", "Would pode ser intenção passada, hábito ou hipótese; o contexto decide.", "Não suponha que todo would seja condicional.", [["I knew the plan would change.", "Eu sabia que o plano mudaria."], ["We were going to call you.", "Íamos ligar para você."]]],
  ["G30", "C1", "Concessão avançada", "Albeit, much as e while reconhecem um ponto sem abandonar o argumento.", "albeit + adjective · much as + clause · while + clause", "A entonação costuma marcar a concessão como um parêntese.", "Albeit não introduz normalmente uma oração completa com sujeito e verbo.", [["The plan is sound, albeit expensive.", "O plano é sólido, embora caro."], ["Much as I agree, we lack evidence.", "Por mais que eu concorde, faltam evidências."]]],
  ["G31", "C2", "Elipse e substituição", "Falantes omitem material recuperável e usam so/do/one para evitar repetição.", "I think so · I might do · the newer one", "O trecho ausente existe no contexto, não no som; reconstrua-o pela conversa.", "Não force a repetição completa quando a elipse é natural.", [["I expected her to leave, and she did.", "Eu esperava que ela fosse embora, e foi."], ["Will it work? I think so.", "Vai funcionar? Acho que sim."]]],
  ["G32", "C2", "Modalidade no passado", "Modal + have + particípio avalia possibilidades, obrigações e arrependimentos passados.", "might/should/could/must + have + participle", "Have se reduz fortemente depois do modal e pode soar como /əv/.", "Não escreva of em should've: a forma é should have.", [["They might have missed the train.", "Talvez tenham perdido o trem."], ["You should have told me sooner.", "Você deveria ter me contado antes."]]],
  ["G33", "C2", "Condicionais mistos", "Misturam uma condição em um tempo com o resultado em outro.", "If + past perfect, would + verb · If + past, would have + participle", "Identifique primeiro quando ocorre a condição e quando ocorre a consequência.", "Não aplique mecanicamente o mesmo tempo aos dois lados.", [["If I'd slept, I'd be sharper now.", "Se eu tivesse dormido, estaria mais atento agora."], ["If I were organized, I wouldn't have missed it.", "Se eu fosse organizado, não teria perdido."]]],
  ["G34", "C2", "Inversão condicional", "Had, were e should podem substituir if em registro formal.", "Had I known... · Were it not for... · Should you need...", "A ordem lembra uma pergunta, mas a entonação continua declarativa.", "Use essa forma com moderação fora de contextos formais.", [["Had I known, I would have waited.", "Se eu soubesse, teria esperado."], ["Should you need help, call me.", "Caso precise de ajuda, ligue para mim."]]],
  ["G35", "C2", "Nominalização e registro", "Substantivos podem condensar processos e criar um tom formal.", "decide → decision · fail → failure · implement → implementation", "Em fala densa, localize o substantivo principal antes de destrinchar os complementos.", "Nominalização excessiva torna frases opacas; verbo direto costuma ser mais claro.", [["The implementation of the policy failed.", "A implementação da política falhou."], ["Their refusal led to a delay.", "A recusa deles levou a um atraso."]]],
  ["G36", "C2", "Discurso indireto e distância", "Verbos de relato e tempos recuados mostram fonte, atitude e distância.", "claim/suggest/acknowledge + that · was said to have", "O verbo de relato revela se o falante aceita, questiona ou apenas atribui a ideia.", "Claim não é sinônimo neutro de say; pode sinalizar dúvida.", [["The report is said to have been altered.", "Dizem que o relatório foi alterado."], ["She acknowledged that the estimate was flawed.", "Ela reconheceu que a estimativa tinha falhas."]]],
].map(([id, level, title, summary, pattern, listeningTip, commonMistake, examples]) => ({ id, level, title, summary, pattern, listeningTip, commonMistake, examples: examples.map(([english, portuguese]) => ({ english, portuguese })), sourceUrl: ref }));
