const stories = [
  S("S01", "The Last Train", "Uma decisão pequena muda a noite de dois desconhecidos.", "A2", "Cotidiano", [["Mia reached the platform as the doors began to close.", "Mia chegou à plataforma quando as portas começaram a fechar."], ["A man inside held the door and called for the driver to wait.", "Um homem lá dentro segurou a porta e pediu ao motorista que esperasse."], ["She got on, out of breath, and thanked him.", "Ela entrou sem fôlego e agradeceu."], ["At the next stop, the train stopped completely.", "Na parada seguinte, o trem parou por completo."], ["The driver announced a long delay.", "O motorista anunciou um longo atraso."], ["Mia and the man laughed. They had both hurried just to sit still.", "Mia e o homem riram. Os dois tinham corrido apenas para ficar parados."]]),
  S("S02", "A Message for Tomorrow", "Um bilhete antigo chega no momento certo.", "B1", "Mistério", [["While moving apartments, Daniel found an envelope behind a drawer.", "Enquanto mudava de apartamento, Daniel encontrou um envelope atrás de uma gaveta."], ["On it, someone had written: Open when you are ready to leave.", "Nele, alguém escreveu: Abra quando estiver pronto para partir."], ["The letter belonged to a woman who had lived there twenty years earlier.", "A carta pertencia a uma mulher que morara ali vinte anos antes."], ["She was afraid to take a job in another country.", "Ela tinha medo de aceitar um emprego em outro país."], ["Daniel was facing the same choice that week.", "Daniel enfrentava a mesma escolha naquela semana."], ["He never learned what she decided, but her courage on the page helped him find his own.", "Ele nunca soube o que ela decidiu, mas a coragem dela no papel o ajudou a encontrar a sua."]]),
  S("S03", "The Quiet Bug", "Uma desenvolvedora encontra o defeito que ninguém via.", "B2", "Tecnologia", [["The payment failures appeared random, which made the team blame the network.", "As falhas de pagamento pareciam aleatórias, o que fez a equipe culpar a rede."], ["Leah noticed that they happened almost exactly at midnight.", "Leah percebeu que aconteciam quase exatamente à meia-noite."], ["She replayed the requests with clocks set to different time zones.", "Ela repetiu as requisições com relógios em fusos diferentes."], ["One old service still treated every date as local time.", "Um serviço antigo ainda tratava toda data como horário local."], ["The fix was three lines; discovering the assumption took three days.", "A correção tinha três linhas; descobrir a suposição levou três dias."], ["In the incident review, Leah wrote that quiet assumptions often make the loudest failures.", "Na revisão do incidente, Leah escreveu que suposições silenciosas costumam causar as falhas mais barulhentas."]]),
  S("S04", "The Borrowed Jacket", "Um casaco perdido revela uma amizade improvável.", "A2", "Amizade", [["Owen took the wrong jacket after a crowded concert.", "Owen pegou o casaco errado depois de um show lotado."], ["In the pocket, he found a bus ticket, a grocery list, and a tiny paper bird.", "No bolso, encontrou uma passagem, uma lista de compras e um pequeno pássaro de papel."], ["The next morning, he returned to the venue.", "Na manhã seguinte, voltou ao local."], ["A woman was waiting with his jacket and the same embarrassed smile.", "Uma mulher esperava com o casaco dele e o mesmo sorriso envergonhado."], ["They exchanged coats, then compared the strange objects in their pockets.", "Trocaram os casacos e compararam os objetos estranhos nos bolsos."], ["A month later, they went to another concert together.", "Um mês depois, foram juntos a outro show."]]),
  S("S05", "The Honest Forecast", "Uma meteorologista precisa escolher entre certeza e honestidade.", "C1", "Trabalho", [["The mayor wanted a definite answer before announcing the outdoor festival.", "O prefeito queria uma resposta definitiva antes de anunciar o festival ao ar livre."], ["Every model showed a different path for the storm.", "Cada modelo mostrava um caminho diferente para a tempestade."], ["Nadia could have offered the most likely forecast and hidden the uncertainty.", "Nadia poderia ter dado a previsão mais provável e escondido a incerteza."], ["Instead, she explained the range of outcomes and what would change her confidence.", "Em vez disso, explicou o leque de resultados e o que mudaria sua confiança."], ["The mayor complained that uncertainty was not useful.", "O prefeito reclamou que incerteza não era útil."], ["Two days later, the storm changed direction, and the flexible plan still worked.", "Dois dias depois, a tempestade mudou de direção, e o plano flexível ainda funcionou."], ["Nadia's refusal to pretend she knew more had made the decision stronger.", "A recusa de Nadia em fingir saber mais tinha fortalecido a decisão."]]),
  S("S06", "The Apology Draft", "Uma mensagem perfeita dá lugar a uma conversa real.", "B2", "Relacionamentos", [["Lucas rewrote his apology twelve times without sending it.", "Lucas reescreveu o pedido de desculpas doze vezes sem enviar."], ["Each version sounded polished and strangely empty.", "Cada versão parecia bem escrita e estranhamente vazia."], ["He wanted to explain his intention before naming the harm.", "Queria explicar a intenção antes de nomear o dano."], ["Finally, he deleted every paragraph except two sentences.", "Por fim, apagou todos os parágrafos menos duas frases."], ["I interrupted you and made your concern seem foolish. I am sorry.", "Eu interrompi você e fiz sua preocupação parecer boba. Sinto muito."], ["The reply came quickly: Thank you. Can we talk tomorrow?", "A resposta veio rápido: Obrigada. Podemos conversar amanhã?"], ["The short message did not repair everything, but it opened the door.", "A mensagem curta não consertou tudo, mas abriu a porta."]]),
  S("S07", "The Museum of Ordinary Things", "Objetos banais ganham valor quando suas histórias aparecem.", "C1", "Cultura", [["The museum displayed no crowns, masterpieces, or famous inventions.", "O museu não exibia coroas, obras-primas nem invenções famosas."], ["Its first room contained a chipped cup, a bus pass, and one child's red shoe.", "A primeira sala continha uma xícara lascada, um passe de ônibus e um sapato vermelho infantil."], ["Visitors initially moved through it with polite confusion.", "No início, visitantes passavam por ela com confusão educada."], ["Then headphones played the owners explaining what each object had survived.", "Então fones tocavam os donos explicando o que cada objeto tinha atravessado."], ["The cup had crossed a border; the bus pass marked a first independent journey.", "A xícara cruzara uma fronteira; o passe marcava uma primeira viagem independente."], ["By the final room, people looked at the contents of their own pockets differently.", "Na última sala, as pessoas olhavam diferente para o conteúdo dos próprios bolsos."]]),
  S("S08", "The Perfect Copy", "Uma cópia digital levanta uma pergunta sobre identidade.", "C2", "Ficção científica", [["The machine reproduced Elena's memories, voice, and habits with flawless precision.", "A máquina reproduziu as memórias, a voz e os hábitos de Elena com precisão impecável."], ["The copy remembered agreeing to the experiment and insisted she was the original.", "A cópia lembrava de concordar com o experimento e insistia ser a original."], ["Researchers proposed tests, but any answer Elena knew, the copy knew too.", "Pesquisadores propuseram testes, mas qualquer resposta que Elena soubesse, a cópia também sabia."], ["Eventually, Elena stopped trying to prove priority and asked a different question.", "Por fim, Elena parou de tentar provar prioridade e fez outra pergunta."], ["What would each of them choose now that their experiences had diverged?", "O que cada uma escolheria agora que suas experiências tinham divergido?"], ["The copy left the laboratory; Elena stayed to shut the project down.", "A cópia deixou o laboratório; Elena ficou para encerrar o projeto."], ["For the first time, neither could predict the other.", "Pela primeira vez, nenhuma conseguia prever a outra."]]),
  S("S09", "Five Minutes Early", "A rotina de pontualidade esconde uma memória familiar.", "B1", "Família", [["Rosa arrived five minutes early for everything.", "Rosa chegava cinco minutos cedo para tudo."], ["Her friends joked that even her surprises were scheduled.", "Os amigos brincavam que até as surpresas dela eram agendadas."], ["One evening, her daughter asked why waiting never seemed to bother her.", "Uma noite, a filha perguntou por que esperar nunca parecia incomodá-la."], ["Rosa remembered standing outside school long after every other child had gone.", "Rosa se lembrou de ficar diante da escola muito depois que todas as crianças tinham ido."], ["Her mother worked two jobs and sometimes missed the bus.", "A mãe dela tinha dois empregos e às vezes perdia o ônibus."], ["Being early, Rosa explained, was how she promised that nobody would wait alone for her.", "Chegar cedo, explicou Rosa, era como prometia que ninguém esperaria sozinho por ela."]]),
  S("S10", "The Unsent Report", "Um analista enfrenta a pressão para suavizar uma conclusão.", "C2", "Ética", [["The report did not accuse anyone of fraud; it showed a pattern that demanded investigation.", "O relatório não acusava ninguém de fraude; mostrava um padrão que exigia investigação."], ["Jon's director asked him to replace 'systematic' with 'isolated' before publication.", "A diretora de Jon pediu que trocasse 'sistemático' por 'isolado' antes da publicação."], ["She called it a matter of tone rather than substance.", "Ela chamou isso de questão de tom, não de substância."], ["Jon knew that one adjective could determine whether anyone looked closer.", "Jon sabia que um adjetivo podia determinar se alguém olharia mais de perto."], ["He sent the report unchanged, along with the evidence supporting the wording.", "Enviou o relatório sem alteração, junto com as evidências que sustentavam a formulação."], ["By morning, his access was suspended and an independent review had begun.", "Pela manhã, seu acesso fora suspenso e uma revisão independente havia começado."], ["He could not know which consequence would last longer.", "Ele não tinha como saber qual consequência duraria mais."]]),
];

